CREATE TABLE crops (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plot_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, variety VARCHAR(150) NULL, planting_date DATE NOT NULL, expected_harvest_date DATE NULL, area_hectares DECIMAL(15,2) NULL, status ENUM('planned','planted','growing','harvested','failed','cancelled') NOT NULL DEFAULT 'planned', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_crops_plot_status (plot_id,status), CONSTRAINT chk_crops_area CHECK (area_hectares IS NULL OR area_hectares > 0), CONSTRAINT chk_crops_expected_harvest CHECK (expected_harvest_date IS NULL OR expected_harvest_date >= planting_date), CONSTRAINT fk_crops_plot FOREIGN KEY (plot_id) REFERENCES plots(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
